local OrionLib = loadstring(game:HttpGet(('https://pastebin.com/raw/xwW9BAbn')))()

local Window = OrionLib:MakeWindow({Name = "Стена Хаб", HidePremium = false, SaveConfig = true, ConfigFolder = "OrionTest"})

--[[
Name = <string> - Имя интерфейса.
HidePremium = <bool> - Показывать ли статус Premium пользователя.
SaveConfig = <bool> - Включает сохранение конфигурации в интерфейсе.
ConfigFolder = <string> - Имя папки, где сохраняются конфигурации.
IntroEnabled = <bool> - Показывать ли анимацию вступления.
IntroText = <string> - Текст для показа в анимации вступления.
IntroIcon = <string> - URL изображения для использования в анимации вступления.
Icon = <string> - URL изображения для отображения на окне.
CloseCallback = <function> - Функция, выполняемая при закрытии окна.
]] local Tab = Window:MakeTab({
    Name = "Вкладка 1",
    Icon = "rbxassetid://4483345998",
    PremiumOnly = false
})

--[[
Name = <string> - Имя вкладки.
Icon = <string> - Иконка вкладки.
PremiumOnly = <bool> - Доступно только для пользователей Sirus Premium.
]] local Section = Tab:AddSection({
    Name = "Секция"
})

Tab:AddParagraph("YouTube Канал","Luvinq_FL0WERS - Roblox Scripts")

Tab:AddParagraph("Discord Сервер","https://discord.gg/RRY7PBhw")

Tab:AddToggle({
    Name = "Переключить скорость ходьбы",
    Default = false,
    Callback = function(Value)
        if Value then
            game.Players.LocalPlayer.Character.Humanoid.WalkSpeed = 60 -- Установите желаемую скорость ходьбы здесь
        else
            game.Players.LocalPlayer.Character.Humanoid.WalkSpeed = 16
        end
    end
})

Tab:AddToggle({
    Name = "Переключить силу прыжка",
    Default = false,
    Callback = function(Value)
        if Value then
            game.Players.LocalPlayer.Character.Humanoid.JumpPower = 200
        else
            game.Players.LocalPlayer.Character.Humanoid.JumpPower = 60
        end
    end
})

